}

private void ApplyHeaderToEmployee(HRS_Employee emp)
{
    emp.FirstName = txtFirstName.Text.Trim();
    emp.LastName = txtLastName.Text.Trim();
    emp.Fullname = string.Format("{0} {1}", emp.FirstName, emp.LastName).Trim();
    emp.FullnameNotVietkey = DCore.Filter.FilterVietkey(emp.Fullname);
    emp.OtherName = txtOtherName.Text.Trim();
    emp.Gender = rdoMale.Checked;

    if (dtmBirthDate.SelectedDate != null)
    {
        DateTime birth = dtmBirthDate.SelectedDate.Value;
        emp.BirthDay = birth.Day;
        emp.BirthMonth = birth.Month;
        emp.BirthYear = birth.Year;
        emp.BirthDateText = birth.ToString("dd/MM/yyyy");
    }

    emp.DepartmentID = EmployeeV2WebLookup.GetInt(ddlDepartment);
    emp.BirthProvinceID = EmployeeV2WebLookup.GetString(ddlBirthProvince);
    emp.OriginProvinceID = EmployeeV2WebLookup.GetString(ddlOriginProvince);
    if (ddlBirthProvince.SelectedIndex > 0)
        emp.BirthAddress = ddlBirthProvince.SelectedItem.Text.Trim();
    if (ddlOriginProvince.SelectedIndex > 0)
        emp.OriginAddress = ddlOriginProvince.SelectedItem.Text.Trim();
    emp.EthnicityID = EmployeeV2WebLookup.GetString(ddlEthnicity);
    emp.ReligionID = EmployeeV2WebLookup.GetString(ddlReligion);
    emp.Tel = txtTel.Text.Trim();
    emp.Mobi = txtMobi.Text.Trim();
    emp.Email = txtEmail.Text.Trim();
}

